def add_data(apps, schema_editor):
    Department = apps.get_model('faculty', 'Department')
    Program = apps.get_model('faculty', 'Program')
    Subject = apps.get_model('faculty', 'Subject')
    Teacher = apps.get_model('faculty', 'Teacher')
    HomePage = apps.get_model('faculty', 'HomePage')
    departments = {}
    for dept_data in DEPARTMENTS:
        departments[dept_data['name']] = Department.objects.create(
            name=dept_data['name'],
            head_of_department=dept_data['head_of_department']
        )
    programs = {}
    for program_data in PROGRAMS:
        program = Program.objects.create(
            name=program_data['name'],
            code=program_data['code'],
            description=program_data['description'],
            coordinator=program_data['coordinator'],
            coordinator_contacts=program_data['coordinator_contacts'],
            department=departments[program_data['department']]
        )
        programs[program_data['name']] = program
    
    for subject_data in SUBJECTS:
        subject = Subject.objects.create(
            name=subject_data['name'],
            description=subject_data['description'],
            credits=subject_data['credits'],
            semester=subject_data['semester'],
            program=programs[subject_data['program']]
        )
        

    for teacher_data in TEACHERS:
        teacher = Teacher.objects.create(
            name=teacher_data['name'],
            position=teacher_data['position'],
            degree=teacher_data['degree'],
            department=departments[teacher_data['department']]
        )
        
    HomePage.objects.create(
        title=HOME_PAGE['title'],
        content=HOME_PAGE['content'],
        contacts=HOME_PAGE['contacts']
    )

def remove_data(apps, schema_editor):
    Department = apps.get_model('faculty', 'Department')
    Program = apps.get_model('faculty', 'Program')
    Subject = apps.get_model('faculty', 'Subject')
    Teacher = apps.get_model('faculty', 'Teacher')
    HomePage = apps.get_model('faculty', 'HomePage')

    for subject_data in SUBJECTS:
        Subject.objects.filter(name=subject_data['name']).delete()

    for program_data in PROGRAMS:
        Program.objects.filter(name=program_data['name']).delete()

    for teacher_data in TEACHERS:
        Teacher.objects.filter(name=teacher_data['name']).delete()

    for dept_data in DEPARTMENTS:
        Department.objects.filter(name=dept_data['name']).delete()

    HomePage.objects.filter(title=HOME_PAGE['title']).delete()

    
    
    

    


